cards=[]
cards.append(compact('jin_feicui','金翡翠','金翡翠与银行家储中望有过十年恩爱而没有孩子的婚姻，随后意外怀孕，生下聪明可爱的小翠。她始终相信自己忠于丈夫，也以为这个孩子终于圆满了家庭，却不知道丈夫早已从多位医生处确认自己不能生育。女儿三岁时，患肺癌的丈夫在临终前拿出检验报告，逼她说出孩子的父亲；她完全无法解释，情绪崩溃，尖叫到大亨闯入病房。储中望去世之后，她继续照顾女儿，却长年靠高声音乐压住丈夫临终质问的回响。她不是怀有神秘生育能力的人，而是不知情接受了杜良植入受精卵的实验受害者。小翠在婚礼突然离去，又使她把多年的恐惧解释成女儿可能来自未知星宿，甚至不敢相信自己真是母亲。她请求卫斯理帮助，也在女儿返回后立刻担心秘密会破坏亲情，希望知情者守口。最后真相说明怀孕和养育都确实发生过，血缘的缺失不能抹掉这二十多年的母女生活。演绎时应让她有谨慎、焦虑、爱与保护欲的矛盾，不能把受伤后的猜疑写成她真能看破外星来历，也不能把悲惨尖叫写成伤人的超能力。','女儿返回并举行第二次正常婚礼；受精卵实验的解释已找到，母女关系继续存在','主角','保住与女儿的关系，并弄清使自己遭受多年误解的生育之谜','在熟悉关系中亲切照顾人，谈及旧事会迟疑、反复确认别人是否相信','女儿失踪或身世可能曝光时先想到失去她，可能以神怪解释未知','她能如实陈述自己的经历，却不能仅凭忠诚知道医学真相',[ab('私人经历与家庭线索','保存和回述婚姻、手术、怀孕及临终质问的经过，为调查提供关键时间链','记忆受长期痛苦影响，解释可能混入恐惧；没有外星感应或特殊生育权能')],[ev('131',1410,1465,'婚姻、怀孕与丈夫患病'),ev('131',1780,1898,'不育报告、质问、崩溃及丈夫死亡'),ev('131',2480,2565,'神怪猜疑与不愿失去女儿'),ev('131',3837,3904,'受精卵实验解释与暗示取消')],aliases=['金女士']))
cards.append(compact('xiao_cui','小翠','小翠是金翡翠十月怀胎并养育成人的女儿，也是大亨疼爱的义女。她小时候活泼亲人，在父亲临终的病房里不懂大人们的悲痛，还以为众人在玩扮妖怪的游戏；这一幕使大亨愿意照料母女。她成年后有自己的爱情和婚姻安排，并不知道出生时已被杜良以实验方式放入与颜色、声音有关的复制思想。第一次婚礼上，陌生男子用古怪的话与她对答，她便在本不该离开的时刻跟随他而去，引起一场惊动众人的寻找。她后来回到家中，只记得自己婚前恐惧、躲进房间，不记得与那人的会面；这并不是她策划欺骗亲友，而是实验者控制和消除记忆造成的后果。水荭重复那些颜色暗语，已不能再唤起同样反应。卫斯理曾因她的出身把她说成不像人，白素坚持她是人，金翡翠确实怀孕生养，母女关系不能被实验名称取消。她最后继续筹办并完成婚礼，原文没有证明她拥有生父的技能、外星血统或主动催眠能力。卡片应保留她在亲密关系中的自然生活和对自己婚礼的期待，也保留尚未完全知晓身世的空白；不能让她一出场就复述研究者的理论，更不能让潜藏思想自动升级成可以支配别人意志的本领。','第二次婚礼正常完成；原预设暗示已失去效力，与杜良会面记忆消失，出生真相未由她自主完整获知','主角','维持自己的爱情、家庭与正常生活，不把他人的研究目的当作人生目标','以普通年轻女子的愿望安排婚事，与亲友自然来往','对记忆缺口只能依据自己保有的感受解释，不能凭空说出被删除的经历','她是有独立人格的人；身世或被植入的思想不等于整个人只是一件实验品',[ab('生活自主与人际交流','成长、恋爱和安排婚礼均有自己的生活意愿，能与周围人建立亲密关系','预设暗示曾违背其意愿控制离场；终局该暗示失效，但不构成所有精神干预免疫')],[ev('131',1845,1875,'幼年性情与大亨结识'),ev('131',2450,2477,'婚礼中的异常暗语'),ev('131',2530,2565,'回家与记忆缺口'),ev('131',3465,3475,'白素维护人的身份与母女关系'),ev('131',3519,3553,'筹婚、重复暗语已无效'),ev('131',3902,3919,'原暗示取消及第二次婚礼')],aliases=['储小翠'],extra={'uncertainties':['原文主要称小翠；储姓来自其社会父亲，未被用于判定遗传来源。','她的生物学父亲没有确证；卫斯理关于大亨的联想仅为猜测。']}))
cards.append(compact('chu_zhongwang','储中望','储中望是一位银行家，与金翡翠感情深厚，在小翠出现以前已相守十年。他早就知道自己因输精管的畸形闭塞不能生育，先后向多位本地及海外医生求证，却没有把这个对婚姻极重要的事实告诉妻子。金翡翠忽然怀孕，使他同时承受惊喜、疑惑和被背叛的猜想；他仍然爱惜出生的女儿，也没有立刻破坏看似幸福的家庭。小翠三岁时，他因肺癌走到生命尽头，终于把多份检查报告摊开，反复追问孩子的父亲究竟是谁。妻子的真诚无法回答医学上的矛盾，他的质问也未能换来想要的解释，最终死在这场悲剧性的对话之中。他不知道金翡翠曾在不知情时被植入别人的受精卵，因此既不能被简单写成早已看穿阴谋，也不能把他的痛苦说成妻子有过不忠的证据。这个人物代表了实验者自称不会影响生活，却实际伤害到的具体家庭。参演明确恢复他最后尚能交谈的病中状态，保留对妻女的感情和对真相的固执；这不是原作复活，不带临终诅咒、亡魂索命或银行财富转化的战斗力。他也应能在获得可靠新证据时面对自己隐瞒病情所造成的沟通困境，而非每次都重演一场质问。','肺癌病中，在向妻子追问女儿生父后去世；未能亲见实验真相','主角','弄清女儿的来源，同时不愿承认自己深爱的家庭可能建立在误解上','用实际检查和文件确认自己身体状况，却把羞于启齿的问题留在心里','生命将尽仍没有解释时会以报告逼问亲人，执著于必须得到一个答案','身体不能生育是事实，妻子背叛并不是由此必然成立的结论',[ab('财务经验与事实核验','作为银行家处理现实事务，并曾反复向不同专家核验生育问题','职业知识不能识破未公开的生物实验；病体行动力和耐力明显受限')],[ev('131',1410,1465,'婚姻和病史'),ev('131',1660,1786,'多处检查与不育事实'),ev('131',1790,1838,'临终质问与死亡'),ev('131',3894,3904,'杜良得知家庭伤害')],profile='ordinary',extra={'version':{'basis':'已死人物显式恢复最后可交谈状态参演','canonical_endpoint':'储中望患肺癌去世，未获知女儿来源的真相','deployment':'恢复最后尚能交谈决策的本人病体；不恢复健康盛年，也不带鬼魂或复活能力。'},'baseline':{'stamina':'晚期肺癌病体，活动与说话均受病势限制，需要照护；不能按健康银行家或战士部署。'},'adaptations':[{'change':'恢复最后尚能交谈的病中本人，并允许新证据进入其判断。','reason':'使回忆中的重要人物可以参与互动，避免把终局重复成固定台词。','power_impact':'没有治愈、延寿、诅咒或额外战斗能力。'}]}))
cards.append(compact('huo_jianping','霍建平','霍建平是有名的外科医生，金翡翠当年因相信他的名声而指定由他实施小手术，没想到真正进手术室工作的另有其人。二十多年后白素查到他时，他已经退休，关掉诊所，在高尔夫球场度过悠闲生活。面对追问，他毫不讳言医生之间使用替身：自己在术前向病人和家属露面，小手术则交给较无名气的医生，而收费仍以名医的标准计算。他认为患者不肯接受推荐的人选，自己只是收取额外的信仰治疗费用，甚至把这说成双方方便、病人毫无损失的安排。白素指出知情选择和收费上的问题，他没有真正认错，只把问题当成行内常见的笑谈。另一方面，他确实还记得储中望与妻子恩爱的样子，也能指认当年替身是后来在电视画面中出现的卢医生，从而使调查走向杜良。他未被证实知道受精卵实验，更没有证据说明他参与制造复制思想；他的责任在于隐瞒真实术者、放弃监督和以专业名声自我辩护。演绎中他应有见惯场面的从容和把伦理问题技术化的圆滑，也能提供真实线索，不能把他写成所有阴谋的幕后主使或拥有杜良的研究成果。','退休并结束诊所，向白素承认替身手术并提供卢医生的线索；无被追责或知晓全部实验的明确后续','阶段性对立者','维护自己的名医声誉、工作便利和对旧日做法的合理化','以轻松谈笑解释医疗行业中的安排，重视自己的时间和专业地位','被质疑收费与隐瞒时转而强调患者执意求名医、实际医生也有资格','对技术效果有自信不等于取得患者知情同意；不得把他未察觉的实验算作共谋',[ab('外科职业经验与旧案记忆','有名外科医生，能够回忆患者夫妻与当年替身术者，提供可核身份线索','已退休、没有常驻诊所；未展示高级复制技术，不把卢医生的实验算作其手术能力')],[ev('131',3091,3097,'姓名及名医身份'),ev('131',3142,3186,'退休、替身收费与自我辩护'),ev('131',3189,3218,'夫妻回忆及指认卢医生'),ev('131',3345,3356,'卢医生的实际工作规模')],profile='expert',aliases=['霍医生']))
cards.append(compact('du_liang_copy','复制杜良','复制杜良被真正的杜良留在勒曼医院，拥有相同的身体外观以及复制而来的部分或全部既有思想，长年替他继续工作，使同仁没有及时发觉本尊已经离开。他看起来仍在研究、使用试管、参与日常生活，却对别人介绍的新发现毫无反应；这不是普通的倔强或反对，而是无法再接收自然产生的新思想和新知识。罗克和同事先以为他发生脑部退化，检查与帮助均不能改变这种状况，后来长期记录才发现，他的语言和动作以六年为周期重复，甚至手臂抬起的角度也相同。牙齿中藏着的微型软片最终带来本尊的信，证实他是为掩护离去而留下的复制体。他本人并不知道医院的调查，也未显示能理解自己身份被揭穿的消息。这个角色的悲剧不在于外貌恐怖，而在于像往常一样辛勤活动，却没有获得吸收新世界的能力。卡片必须与仍在外界创新的杜良分开：不能把后来知识转移的发明、变换容貌后的行为或实验主持权都算给他。为保留互动，只能让场景调用其已有知识可回应的范围；遇到超出输入的消息时表现出不接纳、转回熟悉程序或重复旧反应，而不偷偷补齐无限学习能力。','仍在勒曼医院按既有复制思想工作，对新知识无接收能力；身份已被同仁发现，本人未能理解调查','主角','按照被复制的研究习惯与既有思想维持活动，缺少独立设定新目标的证据','重复原有研究与社交程序，对熟悉事项能表现得与杜良近似','面对不能接收的新信息时不产生相应理解，可能拒绝检查或回到既有行为','与本尊是不同个体；不能用本尊后来的成果补足他的认知缺陷',[ab('既有研究程序与复制思想','拥有杜良被复制时的思想材料，可重复原有研究和语言动作','无法接受新知识，行为呈六年周期；是否本尊故意限制或技术缺陷原文未定'),ab('与本尊近似的身体外观','复制身体使同仁长期未觉察身份替换','只是外形与既有知识相似，没有远程同步本尊或自主制造复制体的证据')],[ev('131',2725,2757,'复制体与长期未被察觉'),ev('131',2780,2829,'新知识不能接收、六年周期'),ev('131',2841,2864,'身份不自知及同步录像'),ev('131',2883,2935,'取牙中微片及本尊信确认')],profile='expert',extra={'baseline':{'mind':'复制思想固定，不能接受自然形成的新思想与新知识；这不是精神攻击免疫，而是严重的认知和适应限制。','intelligence':{'in_combat':'没有新战斗展示，陌生情况不能据本尊学识自动生成新解法。','knowledge':'保留复制时的研究材料，无法学习后续成果。','planning':'行动、语言以六年为周期重复，不能默认形成新的长期方案。','adaptation':'仅调用既有输入范围；超出范围时不能真正理解。'}},'weaknesses':[{'name':'思想无法更新','mechanism':'接受复制思想后不能继续接收自然产生的新思想和知识，语言动作周期重复。','visible':'讨论重要新成果时无反应，长期录像可见固定周期。','discovery':'长期记录、比对行动及本尊留下的信共同确认。','mitigation':'外部人员可照护和调整环境，但原作没有证明他自行修复了学习能力。'}]}))
save(cards)
