def patch(i,txt,refs):
 c=d['weisili_'+i];c['biography']+=' '+txt;c['evidence']+=refs;return c
c=patch('du_liang','《另类复制》揭示他留下复制体掩护离开，以卢医生身份替名医手术，未经同意把带有复制思想的受精卵植入妇女体内，并在成年者的婚礼等关键时刻用预设暗示测试服从。他相信这能证明人类受过外星改造，但实验只证明他自己的植入机制，不能证明整段古代历史。听到储家的伤害后他短暂语塞、称会补偿，却仍拒绝大亨资助和卫斯理干预。终局相关暗示已停止响应，不能把这些受试者当作仍可随意调动的私人军队。',[ev('131',2883,2935,'本尊留下复制体和信，早期所见身份也有不确定性'),ev('131',3671,3698,'对卫和外星人的敌意'),ev('131',3815,3909,'假说、受精卵实验、伤害与停止旧暗示')]);c['aliases']=list(dict.fromkeys(c['aliases']+['卢医生']));c['ooc'].append('《后备》当年所见杜良是否已为复制体无法确定；不把复制体当本尊长期在院的确证。');c['abilities'].append(ab('预植复制思想及条件触发','借实验设备把特定思想与受精卵结合，在个体成长后以预设颜色和声音暗示启动行动','需要事先处理、长期生长与对应信号；本案旧暗示已失效，不能对陌生人即时施放，古代人类普遍受控仅是他的假说','使用前先核受试对象是否经过实际处理，不能把所有人类都判为目标'.split('，'),kind='生物技术'))
c=patch('luo_ke','《另类复制》中他与同事调查杜良的异常，经过长期记录发现六年重复，从复制体牙中取出微片，才确认本尊离去。他既赞叹杜良的才智，又气恼好友不分享成果，赞成劝阻思想复制广泛实施；这显示其立场会随具体风险变化，而非永远赞同每一种实验。秘密麻醉并取物仍体现医院越过知情同意的行事方式。',[ev('131',2780,2829,'长期观察及复制体限制'),ev('131',2883,2935,'麻醉取片及信确认'),ev('131',3008,3038,'反对广泛思想复制'),ev('131',3095,3104,'对好友保密的气愤')]);c['version']['canonical_endpoint']='《另类复制》继续在勒曼医院研究和联络，调查复制杜良并希望遏止思想复制扩散';c['version']['deployment']=c['version']['canonical_endpoint']+'；个人不携带医院全部设备。'
patch('ge_deng','《另类复制》仍作为罗克的研究同仁被明确提到，曾一起试图检查杜良的异常；本尊留下的信也将两人视为相信他不会伤害人类的老友。这里不是他已学会思想复制的证据。',[ev('131',2810,2817,'与罗克尝试检查'),ev('131',2924,2927,'本尊信中的老友关系')])
patch('liang_sheng','《另类复制》中对思想复制的机制仍需依靠杜良留下的结果推断，他不能自行补齐这项成果。他与同仁认为广泛思想复制可能对人类造成祸害；谈及不知情怀孕时，最初也误以为金女士说谎，经过追问才从麻醉经历寻找解释。',[ev('131',2790,2795,'方法缺陷或故意限制未定'),ev('131',3008,3069,'风险态度与推理纠正')])
patch('dian_xiwei','《另类复制》开头，卫斯理在她不知情时又找九名催眠师尝试，六人无法使她进入催眠、两人几乎反被催眠，只有一人能接触普通记忆，却仍打不开封存段落。这个结果说明对一般催眠的强抵抗和外来封存的坚固，不能外推为对所有精神力量免疫，也不使她获得可随意向别人施放的反催眠术。',[ev('131',14,57,'九名催眠师的结果与记忆仍封存')]);d['weisili_dian_xiwei']['baseline']['mind']='对一般催眠有很强抵抗，九名高手中仅一人能催眠普通记忆，两人几乎受反作用；努力大师曾令她重演封存片段。不能据此推出所有精神干预免疫，封存记忆仍未自行恢复。'
patch('feinandu','后来他与卫斯理计划继续监视当地异常，提出设置观察站，陶启泉愿提供经费。这仍是调查计划和人际支持，没有证明所有站点已建成，更没有证明他们已控制上空可能存在的飞行器。',[ev('131',64,116,'监视计划、猜测与资助')])
patch('nuli_master','后续九名催眠师仍无法重现他所打开的封存经历，使其这次专门技巧更显独特；原作没有因此撤销他至少三年失能的代价。',[ev('131',14,57,'其他大师失败和原有代价背景')])
patch('wei_sili','在追索典希微被封存的记忆时，他没有满足于努力大师的重演，后来又在她不知情的情况下找九位催眠师尝试；为逼杜良现身，他以公开实验者身份及其受试者相威胁。求知与阻止危害可能使他侵犯隐私甚至牵连无辜，不能把他改写成每次都先获得同意的温和调查者。',[ev('131',14,57,'未经知情的催眠尝试'),ev('131',3643,3675,'公开压力与杜良指其祸延无辜')])
patch('bai_su','面对小翠的特殊出生，她明确坚持金翡翠怀胎生养的母亲身份，也拒绝把被实验影响的女儿说成不是人；她区分解释身世与贬损人格，不让猎奇盖过当事人的生活。',[ev('131',3465,3475,'人的身份及母女关系')])
patch('xiao_guo','追查杜良受试者时，他沿名医替身的工作关系查找女病人，先查到三十七位，一个月后再找到十六位，逐一核对其后怀孕及孩子成长；未联系到的其余案例仍是据同模式推断。',[ev('131',3489,3508,'追踪方案'),ev('131',3614,3641,'确证人数及后续十六人')])
CARDS.write_text(json.dumps(allcards,ensure_ascii=False,indent=2)+'\n',encoding='utf8')
def r(n,i,b,role='重要配角'):return(n,i,role,b)
cover('131',[r('卫斯理','wei_sili','思想复制与母女之谜调查','主角'),r('白素','bai_su','找霍医生、维护人的身份','主角'),r('小郭','xiao_guo','追查替身医生及受试妇女'),r('陶启泉','tao_qiquan','费南度项目支持、案件参与'),r('大亨','da_heng','母女保护、旧事目击与资助提议'),r('朱槿','zhu_jin','调查联络与网络查询'),r('水荭','adventure_shui_hong','伴娘、暗语目击及查问'),r('典希微','dian_xiwei','催眠后续与记忆边界'),r('费南度','feinandu','继续调查计划'),r('金翡翠','jin_feicui','生育与家庭伤害的核心当事人','主角'),r('小翠','xiao_cui','婚礼失踪与受试者人格','主角'),r('储中望','chu_zhongwang','婚姻回忆、临终冲突','主角'),r('霍建平','huo_jianping','替身手术隐瞒和身份线索','阶段性对立者'),r('杜良','du_liang','未经同意实施思想实验','阶段性对立者'),r('复制杜良','du_liang_copy','留院掩护及学习停滞','主角'),r('罗克','luo_ke','复制体研究与劝阻'),r('亮声','liang_sheng','医院协调及研究边界'),r('哥登','ge_deng','参与异常研究和旧友关系')],[('努力大师','仅开头回顾前篇能力损耗，没有本篇新行动；主卡保留并补后续对照'),('温宝裕、红绫','开篇社会位置或既有经历简提，未在本案形成独立新行动'),('新郎、其他婚礼宾客、其他受试者','一次背景和未具身份的样本集合，无独立角色逻辑或反派行动'),('其他催眠师、医院青年研究者、驾驶员','一次协助或未分名的调查背景，不据职称补造人物')],['复制杜良与杜良分别建卡，早期医院所见是否已经为复制体仍不确定。','实验发生与设定中触发有效，不足以确证杜良关于古代外星统治的整个理论。','小翠生父未定，大亨血缘只是卫斯理的猜想；社会母女关系不能因实验而取消。'])
